<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/refunds.php';$me=require_permission('DUYET_HUY');handle_form(function()use($me){switch(post('action')){case'duyet':approve_cancel($me,(int)post('request'),post('duyet')==='1',vnd(post('so_tien'),true),post('ket_qua'));break;case'tao_hoan':reserve_refund($me,(int)post('request'),post('goc'),vnd(post('so_tien')),post('request_key'));break;case'xac_nhan':must(post('confirmed')==='1','Cần xác nhận đã hoàn tiền thực tế.');confirm_refund($me,post('id'),post('nguon'),post('tham_chieu'),post('ngay'));break;default:throw new AppError('Thao tác không hợp lệ.');}},'nhan_vien/huy_hoan.php');page_start('Yêu cầu hủy và hoàn tiền','Phê duyệt không đồng nghĩa tiền đã được hoàn. Mỗi lệnh hoàn phải có chứng từ thực tế.');
$rows=db_all('SELECT r.* FROM yeu_cau_huy r ORDER BY id DESC LIMIT 200');foreach($rows as$r){$h=db_one('SELECT * FROM hop_dong WHERE so_hop_dong=?',[$r['so_hop_dong']]);if(!contract_access($me,$h))continue;echo '<section class="panel"><h2>#'.(int)$r['id'].' · '.e($r['so_hop_dong']).'</h2><p>'.badge($r['trang_thai']).' '.e($r['ly_do']).'</p><p>Tiền ròng đã nhận: '.e(money(money_total($h['so_hop_dong']))).'</p>';if($r['trang_thai']==='CHO_DUYET'){token_form();field('request','',$r['id'],'hidden');select_field('duyet','Quyết định',['1'=>'Duyệt hủy','0'=>'Từ chối'],'1',true);field('so_tien','Số tiền được hoàn theo thỏa thuận',0,'number','min="0" required');textarea('ket_qua','Căn cứ / nội dung thỏa thuận');echo '<button name="action" value="duyet">Lưu quyết định</button></form>';}
elseif($r['trang_thai']==='DA_DUYET'&&can($me,'DUYET_HOAN')){echo '<p>Được hoàn: '.e(money($r['tien_duoc_hoan'])).' · '.e($r['ket_qua']).'</p>';token_form();field('request','',$r['id'],'hidden');field('request_key','',new_request_key(),'hidden');select_field('goc','Khoản thu gốc',choices("SELECT ma_hoa_don,CONCAT(ma_hoa_don,' · ',so_tien_thu) label FROM hoa_don WHERE so_hop_dong=? AND loai_giao_dich='THU' AND trang_thai='SUCCESS'",'ma_hoa_don','label',[$h['so_hop_dong']]),'',true);field('so_tien','Số tiền đề nghị hoàn','','number','min="1" required');echo '<button name="action" value="tao_hoan">Tạo lệnh hoàn / giữ hạn mức</button></form>';foreach(db_all("SELECT * FROM hoa_don WHERE yeu_cau_huy_id=? AND loai_giao_dich='HOAN_TIEN'",[$r['id']])as$p){echo '<details><summary>'.e($p['ma_hoa_don'].' · '.money($p['so_tien_thu'])).' '.strip_tags(badge($p['trang_thai'])).'</summary>';if($p['trang_thai']==='CHO_XAC_NHAN'){token_form();field('id','',$p['ma_hoa_don'],'hidden');field('nguon','Ngân hàng / nguồn chứng từ','','text','required');field('tham_chieu','Mã giao dịch hoàn thực tế','','text','required');field('ngay','Ngày hoàn',date('Y-m-d\TH:i'),'datetime-local','required');echo '<label><input type="checkbox" name="confirmed" value="1" required>Đã hoàn tiền thực tế, đã đối chiếu chứng từ</label><button name="action" value="xac_nhan">Ghi nhận hoàn thành công</button></form>';}echo '</details>';}}if($r['trang_thai']==='DA_DUYET'&&!can($me,'DUYET_HOAN'))notice('Quản trị viên hoặc nhân viên có quyền hoàn tiền sẽ xử lý khoản hoàn đã duyệt.');echo '</section>';}
page_end();
